methods.fixedCode:
[Authorize]
[HttpGet("{orderId:int}")]
public async Task<IActionResult> GetOrder(int orderId)
{
    try
    {
        var customerId = User.Identity?.Name;
        if (string.IsNullOrWhiteSpace(customerId))
            return Unauthorized();

        var order = await _db.Orders
            .FirstOrDefaultAsync(o => o.Id == orderId
                                   && o.CustomerId == customerId);

        if (order is null)
            return NotFound();

        _audit.RecordOrderRead(customerId, orderId);
        return Ok(order);
    }
    catch (Exception ex)
    {
        return _errors.CreateErrorResponse(ex);
    }
}

